var tokens=Object.keys(glossary).sort(function(a,b){return b.length-a.length;});
function translated(s){s=String(s==null?'':s);if(Object.prototype.hasOwnProperty.call(dict,s))return dict[s];var parts=[],i=0;while(i<s.length){var match=null;for(var n=0;n<tokens.length;n++){if(s.substr(i,tokens[n].length)===tokens[n]){match=tokens[n];break;}}if(match){parts.push(" "+glossary[match]+" ");i+=match.length;}else{parts.push(s.charAt(i++));}}return parts.join('').replace(/ +/g,' ').trim();}
