function savePrefs(){if(!prefFile)return;try{var tmp=prefFile+'.new';fs.writeFileSync(tmp,JSON.stringify(prefs,null,2));fs.renameSync(tmp,prefFile);}catch(e){say('Settings could not be saved: '+e.message,true);}}
function say(message,error){if(notice){notice.textContent=message;notice.dataset.error=error?'1':'0';notice.style.color=error?(prefs.theme==='Daylight'?'#a72929':'#ff9b9b'):(prefs.theme==='Daylight'?'#226346':'#b9ead5');}}
function fail(message){throw new Error(message);}
function ready(){if(!g.$gameParty||!g.$gameVariables||!g.$gamePlayer)fail('Start or load a game first.');}
function integer(v,min,max){var n=Number(v);if(!isFinite(n)||Math.floor(n)!==n||n<min||n>max)fail('Enter an integer from '+min+' to '+max+'.');return n;}
function number(v){var n=Number(v);if(!isFinite(n))fail('Enter a finite number.');return n;}
function database(kind){return {items:g.$dataItems,weapons:g.$dataWeapons,armors:g.$dataArmors,states:g.$dataStates,skills:g.$dataSkills,actors:g.$dataActors,maps:g.$dataMapInfos}[kind];}
function valid(kind,id){var db=database(kind);id=integer(id,1,db?db.length-1:0);if(!db[id])fail('This ID does not exist in this game.');return db[id];}
function actor(id){valid('actors',id);return $gameActors.actor(Number(id));}
function varId(id){return integer(id,1,$dataSystem.variables.length-1);}
function switchId(id){return integer(id,1,$dataSystem.switches.length-1);}
function value(v){if(typeof v==='string'){try{return JSON.parse(v);}catch(_){return v;}}return v;}
function shown(v){return typeof v==='string'?JSON.stringify(v):JSON.stringify(v)==null?String(v):JSON.stringify(v);}
function applyVar(id,v){ready();id=varId(id);v=value(v);if(Object.prototype.hasOwnProperty.call(locks.variables,id))locks.variables[id]=v;$gameVariables.setValue(id,v);return $gameVariables.value(id);}
function lockVar(id,v,on){ready();id=varId(id);if(on){locks.variables[id]=value(v);applyVar(id,v);}else delete locks.variables[id];}
function applySwitch(id,v){ready();id=switchId(id);if(Object.prototype.hasOwnProperty.call(locks.switches,id))locks.switches[id]=!!v;$gameSwitches.setValue(id,!!v);}
function lockSwitch(id,v,on){ready();id=switchId(id);if(on){locks.switches[id]=!!v;applySwitch(id,v);}else delete locks.switches[id];}
function quantity(kind,id,n){ready();var item=valid(kind,id);n=integer(n,0,$gameParty.maxItems(item));if(Object.prototype.hasOwnProperty.call(locks.inventory,kind+':'+id))locks.inventory[kind+':'+id]=n;$gameParty.gainItem(item,n-$gameParty.numItems(item),false);return $gameParty.numItems(item);}
function money(n){ready();n=integer(n,0,$gameParty.maxGold());if(locks.gold!==null)locks.gold=n;$gameParty.gainGold(n-$gameParty.gold());return $gameParty.gold();}
function lockMoney(n,on){ready();locks.gold=on?integer(n,0,$gameParty.maxGold()):null;if(on)money(n);}
var resourceOverrides={};
function resourceOverride(a,key){return !!(a&&typeof a.actorId==='function'&&(resourceOverrides[a.actorId()+':'+key]||locks.resources[a.actorId()+':'+key]));}
function resource(id,key,n){ready();var a=actor(id),max=key==='hp'?a.mhp:key==='mp'?a.mmp:a.maxTp();n=Math.min(max,Math.max(0,number(n)));resourceOverrides[id+':'+key]=true;if(locks.resources[id+':'+key]){locks.resources[id+':'+key].value=n;locks.resources[id+':'+key].max=false;}if(key==='hp')a.setHp(n);else if(key==='mp')a.setMp(n);else a.setTp(n);a['_'+key]=n;tick();return a[key];}
function restoreResource(key,id){ready();var members=id===undefined?$gameParty.members():[actor(id)];members.forEach(function(a){var max=key==='hp'?a.mhp:key==='mp'?a.mmp:a.maxTp(),spec=locks.resources[a.actorId()+':'+key],wasMax=spec&&spec.max;resource(a.actorId(),key,max);if(spec&&wasMax)spec.max=true;});live();}
function maximum(id,key,n,on){ready();var a=actor(id),k=id+':'+key;if(on)caps[k]=integer(n,key==='hp'?1:0,9999999);else delete caps[k];a.refresh();tick();return key==='hp'?a.mhp:key==='mp'?a.mmp:a.maxTp();}
function resourceLock(id,key,n,on,max){ready();id=Number(id);actor(id);var k=id+':'+key;if(on)locks.resources[k]={value:number(n),max:!!max};else delete locks.resources[k];tick();}
function forceState(a,id){a.addState(id);if(!a.isStateAffected(id)){a._states.push(id);a.sortStates();a.resetStateCounts(id);}}
function state(id,stateId,on,pin){ready();var a=actor(id);stateId=Number(stateId);valid('states',stateId);var k=id+':'+stateId;if(pin){locks.states[k]=!!on;if(prefs.rememberStates)prefs.stateRules[k]=!!on;}else{delete locks.states[k];delete prefs.stateRules[k];}savePrefs();if(on){if(pin)forceState(a,stateId);else a.addState(stateId);}else a.removeState(stateId);return a.isStateAffected(stateId);}
function restoreStateRules(){if(!prefs.rememberStates)return;Object.keys(prefs.stateRules).forEach(function(k){var p=k.split(':');if($dataActors[Number(p[0])]&&$dataStates[Number(p[1])])state(Number(p[0]),Number(p[1]),prefs.stateRules[k],true);});}
function skill(id,skillId,on){ready();var a=actor(id);skillId=Number(skillId);valid('skills',skillId);if(on)a.learnSkill(skillId);else a.forgetSkill(skillId);return a.isLearnedSkill(skillId);}
function temporary(s){return s&&((s.autoRemovalTiming||0)>0||s.removeAtBattleEnd||s.removeByWalking||s.removeByDamage);}
function recover(){ready();$gameParty.members().forEach(function(a){var prefix=a.actorId()+':';Object.keys(locks.states).forEach(function(k){var id=Number(k.split(':')[1]);if(k.indexOf(prefix)===0&&(id===a.deathStateId()||temporary($dataStates[id]))){delete locks.states[k];delete prefs.stateRules[k];}});var keep=a.states().filter(function(s){return !temporary(s)&&s.id!==a.deathStateId();}).map(function(s){return s.id;});a.recoverAll();keep.forEach(function(id){forceState(a,id);});a.clearBuffs();['hp','mp','tp'].forEach(function(key){restoreResource(key,a.actorId());});});savePrefs();tick();}
function clearLocks(preserveRules){locks={variables:{},switches:{},inventory:{},resources:{},states:{},gold:null};caps={};resourceOverrides={};flags.noclip=false;flags.mouse=false;flags.enemyOne=false;if(!preserveRules){prefs.stateRules={};savePrefs();}render();say('All runtime locks, resource overrides and movement/battle toggles released.');}
function tick(){if(!g.$gameParty)return;Object.keys(locks.variables).forEach(function(id){var v=locks.variables[id];if(shown($gameVariables._data[Number(id)])!==shown(v))$gameVariables.setValue(Number(id),v);});Object.keys(locks.switches).forEach(function(id){if($gameSwitches.value(Number(id))!==locks.switches[id])$gameSwitches.setValue(Number(id),locks.switches[id]);});Object.keys(locks.inventory).forEach(function(k){var p=k.split(':');quantity(p[0],Number(p[1]),locks.inventory[k]);});Object.keys(locks.resources).forEach(function(k){var p=k.split(':'),a=actor(Number(p[0])),spec=locks.resources[k],key=p[1],max=key==='hp'?a.mhp:key==='mp'?a.mmp:a.maxTp(),v=Math.max(0,Math.min(max,spec.max?max:spec.value));if(a['_'+key]!==v){a['_'+key]=v;if(key==='hp'&&v>0&&a.isDeathStateAffected())a.removeState(a.deathStateId());}});Object.keys(locks.states).forEach(function(k){var p=k.split(':'),a=actor(Number(p[0])),id=Number(p[1]),on=locks.states[k];if(on&&!a.isStateAffected(id))forceState(a,id);else if(!on&&a.isStateAffected(id))a.removeState(id);});if(flags.enemyOne&&g.$gameTroop&&$gameParty.inBattle())$gameTroop.members().forEach(function(e){if(e.isAlive()&&e.hp!==1)e.setHp(1);});}
function battle(result){ready();if(!$gameParty.inBattle())fail('This action needs an active battle.');if(result==='win'){$gameTroop.members().forEach(function(e){e.setHp(0);});BattleManager.processVictory();}else{$gameParty.battleMembers().forEach(function(a){delete locks.resources[a.actorId()+':hp'];delete locks.states[a.actorId()+':'+a.deathStateId()];a.setHp(0);forceState(a,a.deathStateId());a._hp=0;});BattleManager.processDefeat();}}
function scene(kind){ready();if($gameParty.inBattle())fail('Close the battle before opening a save/load menu.');hide();SceneManager.push(kind==='save'?Scene_Save:Scene_Load);}
function transfer(id,x,y){ready();id=Number(id);valid('maps',id);if($gameParty.inBattle())fail('Leave the battle before transferring.');x=integer(x,0,9999);y=integer(y,0,9999);var uri=new URL('data/Map'+('000'+id).slice(-3)+'.json',document.baseURI).href;return new Promise(function(resolve,reject){var req=new XMLHttpRequest();req.open('GET',uri);req.onload=function(){try{if(req.status>=400)fail('Map could not be loaded.');var map=JSON.parse(req.responseText);if(x>=map.width||y>=map.height)fail('Coordinates exceed this map ('+map.width+' × '+map.height+').');$gamePlayer.reserveTransfer(id,x,y,2,0);hide();if(!(SceneManager._scene instanceof Scene_Map))SceneManager.goto(Scene_Map);resolve();}catch(e){reject(e);}};req.onerror=function(){reject(new Error('Map could not be read.'));};req.send();});}
